object Vault:
  opaque type Secret = String                  // transparent only in this file
  def load(id: String): Secret = readFromVault(id)
  extension (s: Secret) def reveal(using AdminToken): String = s

// holding a Secret is not the same as being able to read it
def audit(secret: Secret, token: AdminToken): String = secret.reveal(using token)
